public ARGPostalCodeResponse getPostalCodeRecord(ARGPostalCodeRequest _request)
{
    var response = new ARGPostalCodeResponse();

    changecompany(_request.parmDataAreaId())
    {
        response = this.getPostalCode(_request.parmPostalCodeClass());
        return response;
    }
}

public ARGPostalCodeResponse getPostalCode(ARGPostalCodeClass _postalCodeClass)
{
    ARGPostalCodes postalCodes;
    ARGPostalCodeResponse response = new ARGPostalCodeResponse();

    try
    {
        if (_postalCodeClass.parmPostalCode())
        {
            while select postalCodes
                where postalCodes.PostalCode == _postalCodeClass.parmPostalCode()
            {                
                if(postalCodes)
                {
                    response.parmSuccess(true);
                    response.parmDebugMessage("Postal code record");
                }
            }
        }
    }
    catch (Exception::Error)
    {
        throw Exception::Error;
    }

    return response;
}

public List createLine(ARGPostalCodes _postalCodes)
{
    List lines = new List(Types::Class);
    ListIterator   literator;
    ARGPostalCodeLinesClass postalCodeLines;

    postalCodeLines.parmRoute(_postalCodes.Route);
    postalCodeLines.parmCompany(_postalCodes.Company);
    postalCodeLines.parmHour(_postalCodes.Hour);
    postalCodeLines.parmCity(_postalCodes.City);
    postalCodeLines.parmState(_postalCodes.State);
    postalCodeLines.parmPostalCode(_postalCodes.PostalCode);

    lines.addEnd(postalCodeLines);

    return lines;
}
